export type GapValue = number | readonly [number, number] | readonly [number, number, number, number];

export interface GapStyle {
  outerGap?: GapValue;
  innerGap?: GapValue;
  outerTop?: number;
  outerRight?: number;
  outerBottom?: number;
  outerLeft?: number;
  innerTop?: number;
  innerRight?: number;
  innerBottom?: number;
  innerLeft?: number;
  [key: string]: unknown;
}

const directionalProperties = [
  "outerTop",
  "outerRight",
  "outerBottom",
  "outerLeft",
  "innerTop",
  "innerRight",
  "innerBottom",
  "innerLeft"
] as const;

function sides(value: GapValue): readonly [number, number, number, number] {
  const values = typeof value === "number" ? [value] : [...value];
  if (values.length !== 1 && values.length !== 2 && values.length !== 4) {
    throw new RangeError("gap must contain one, two, or four values");
  }
  if (values.some((item) => !Number.isFinite(item))) {
    throw new RangeError("gap values must be finite");
  }
  if (values.length === 1) return [values[0], values[0], values[0], values[0]];
  if (values.length === 2) return [values[0], values[1], values[0], values[1]];
  return [values[0], values[1], values[2], values[3]];
}

export function expandGaps(style: Readonly<GapStyle>): GapStyle {
  for (const property of directionalProperties) {
    if (Object.prototype.hasOwnProperty.call(style, property)) {
      const value = style[property];
      if (value !== undefined && !Number.isFinite(value)) {
        throw new RangeError("gap values must be finite");
      }
    }
  }

  const result: GapStyle = { ...style };
  const expand = (name: "outerGap" | "innerGap", prefix: "outer" | "inner"): void => {
    const value = style[name];
    if (value === undefined) return;
    const values = sides(value);
    const names = [prefix + "Top", prefix + "Right", prefix + "Bottom", prefix + "Left"];
    names.forEach((property, index) => {
      if (result[property] === undefined) result[property] = values[index];
    });
  };

  expand("outerGap", "outer");
  expand("innerGap", "inner");
  return result;
}

