import { expandGaps } from './solution';
import type { GapStyle } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsRange(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const source: GapStyle = {
  outerGap: [1, 2],
  innerGap: [3, 4, 5, 6],
  outerLeft: 9,
  innerTop: undefined,
  color: 'red'
};
const expanded = expandGaps(source);
assert(expanded !== source, 'returns a new object');
equal(expanded.outerGap, source.outerGap, 'outer shorthand is preserved');
equal(expanded.innerGap, source.innerGap, 'inner shorthand is preserved');
equal(expanded.color, 'red', 'unrelated property is preserved');
equal(expanded.outerTop, 1, 'pair vertical top');
equal(expanded.outerRight, 2, 'pair horizontal right');
equal(expanded.outerBottom, 1, 'pair vertical bottom');
equal(expanded.outerLeft, 9, 'explicit directional value wins');
assert(Object.prototype.hasOwnProperty.call(expanded, 'innerTop'), 'explicit undefined remains an own property');
equal(expanded.innerTop, undefined, 'explicit undefined is not replaced');
equal(expanded.innerRight, 4, 'four-value right');
equal(expanded.innerBottom, 5, 'four-value bottom');
equal(expanded.innerLeft, 6, 'four-value left');
equal(source.outerTop, undefined, 'input is not mutated');
equal(source.innerRight, undefined, 'input receives no expanded values');

const scalar = expandGaps({ outerGap: 7, innerGap: 0 });
for (const key of ['outerTop', 'outerRight', 'outerBottom', 'outerLeft'] as const) equal(scalar[key], 7, `scalar outer ${key}`);
for (const key of ['innerTop', 'innerRight', 'innerBottom', 'innerLeft'] as const) equal(scalar[key], 0, `scalar inner ${key}`);

const proto = { outerTop: 99 };
const inherited = Object.create(proto) as GapStyle;
(inherited as { outerGap: number }).outerGap = 4;
const inheritedResult = expandGaps(inherited);
equal(inheritedResult.outerTop, 4, 'inherited directional value is not explicit');
assert(Object.prototype.hasOwnProperty.call(inheritedResult, 'outerTop'), 'expanded directional value is own');

throwsRange(() => expandGaps({ outerGap: [] as unknown as readonly [number, number] }), 'empty shorthand rejected');
throwsRange(() => expandGaps({ outerGap: [1, 2, 3] as unknown as readonly [number, number] }), 'three-value shorthand rejected');
throwsRange(() => expandGaps({ innerGap: [1, 2, 3, 4, 5] as unknown as readonly [number, number, number, number] }), 'five-value shorthand rejected');
throwsRange(() => expandGaps({ outerGap: Number.NaN }), 'non-finite scalar rejected');
throwsRange(() => expandGaps({ innerGap: [1, Number.POSITIVE_INFINITY] }), 'non-finite shorthand member rejected');
throwsRange(() => expandGaps({ outerRight: Number.NEGATIVE_INFINITY }), 'non-finite directional value rejected');

